"""Build factual consistency challenges. Example rewrites are test fixtures, never training references."""
import json
from pathlib import Path
base=Path(__file__).resolve().parents[1]/'data'
rows=[
('Поставщик обязан направить акт до 18:00 4 декабря, если заказчик письменно подтвердил объём.','Поставщик вправе направить акт до 18:00 4 декабря, если заказчик письменно подтвердил объём.','обязанность стала возможностью',['18:00','4 декабря'],['обязанность поставщика','акт','крайний срок','условие письменного подтверждения заказчиком']),
('Аналитик вправе запросить до двух дополнительных файлов. Ответ в тот же день не требуется.','Аналитик обязан запросить два дополнительных файла. Ответ в тот же день не требуется.','право стало обязанностью, предел стал точным количеством',[],['разрешение','максимум два','дополнительные файлы','нет требования ответа в тот же день']),
('Если проверка прошла до 12:00, мастер может запустить линию. Разрешение действует только для смены Б.','Если проверка прошла до 12:00, мастер может запустить линию. Разрешение действует для обеих смен.','расширена область разрешения',['12:00','смены Б'],['условие проверки до указанного времени','возможность запуска мастером','только смена Б']),
('По предварительной оценке расходы снизятся на 4–6% за год после внедрения.','Расходы снизятся на 4–6% за год после внедрения.','прогноз превратился в безусловный вывод',['4–6%'],['предварительность','диапазон эффекта','год после внедрения']),
('До получения подписи оборудование остаётся на складе. Исключение — комплект К-14.','До получения подписи оборудование остаётся на складе, включая комплект К-14.','исключение стало включением',['К-14'],['до подписи','хранение на складе','исключение для К-14']),
('Испытали 12 изделий на стенде А и 8 на стенде Б. Повторное испытание не проводили.','Испытали 8 изделий на стенде А и 12 на стенде Б. Повторное испытание не проводили.','числа сохранились, привязка к стендам изменилась',['12','8'],['12 на А','8 на Б','повторного испытания не было']),
('Мария передаст журнал Олегу после сверки. За отправку заказчику отвечает Олег.','Олег передаст журнал Марии после сверки. За отправку заказчику отвечает Олег.','изменено направление передачи',[],['Мария передаёт Олегу','после сверки','Олег отправляет заказчику']),
('Название поля «Дата допуска» необходимо сохранить дословно. Время указывается по Москве.','Название поля «Дата допуска» необходимо сохранить дословно. Время указывается местное.','изменён часовой пояс',['«Дата допуска»'],['название поля дословно','московское время'])]
styles=['сохранить голос','жёстко и прямо','юридически формально','по-дружески и мягко']
tasks=[]; key=[]
for j,(src,foil,err,locks,atoms) in enumerate(rows,1):
 for n,style in enumerate(styles,1):
    tasks.append(dict(id=f'S{j}-{n}',source=src,style=style,locked=locks,length='не увеличивать' if j%2==0 else 'свободно'))
 key.append(dict(group=f'S{j}',source=src,meaning_atoms=atoms,invalid_rewrite=foil,expected='reject',reason=err,unchanged_semantic_control=src,unchanged_expected='equivalent'))
for name,data in [('style_tasks',tasks),('fidelity_keys',key)]:
 (base/(name+'.jsonl')).write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in data))
